import 'package:flutter/cupertino.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../main.dart';
import '../models/app_models.dart';
import '../theme/app_theme.dart';

class MaintenanceHistoryPage extends ConsumerWidget { const MaintenanceHistoryPage({super.key});
  @override Widget build(BuildContext context,WidgetRef ref){final app=ref.watch(appProvider);final records=<MaintenanceRecord>[if(app.oil!=null) MaintenanceRecord(title:'Cambio de aceite',type:'oil',date:app.oil!.date,mileage:app.oil!.lastMileage),...app.pads.map((v)=>MaintenanceRecord(title:'Pastillas de freno',type:'pads',date:v.date,mileage:v.mileage,notes:v.notes)),...app.fluid.map((v)=>MaintenanceRecord(title:'Líquido de frenos',type:'fluid',date:v.date,mileage:v.mileage,notes:v.notes))]..sort((a,b)=>b.date.compareTo(a.date));return ListView(padding:const EdgeInsets.fromLTRB(20,20,20,110),children:[Text('Mantenimiento',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:6),const Text('Historial cronológico de tu vehículo'),const SizedBox(height:18),FilledButton.icon(onPressed:()=>_choose(context),icon:const Icon(CupertinoIcons.plus),label:const Text('Registrar mantenimiento')),const SizedBox(height:22),if(records.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(24),child:Text('Aún no tienes mantenimientos registrados.'))),...records.map((r)=>_RecordTile(record:r))]);}
  void _choose(BuildContext context)=>showModalBottomSheet(context:context,showDragHandle:true,builder:(_)=>SafeArea(child:Column(mainAxisSize:MainAxisSize.min,children:[ListTile(leading:const Icon(CupertinoIcons.drop_fill,color:AppTheme.teal),title:const Text('Cambio de aceite'),onTap:(){Navigator.pop(context);showOilForm(context);}),ListTile(leading:const Icon(CupertinoIcons.wrench,color:AppTheme.teal),title:const Text('Pastillas de freno'),onTap:(){Navigator.pop(context);showPadsForm(context);}),ListTile(leading:const Icon(CupertinoIcons.drop,color:AppTheme.teal),title:const Text('Líquido de frenos'),onTap:(){Navigator.pop(context);showFluidForm(context);})])));
}
class _RecordTile extends StatelessWidget { const _RecordTile({required this.record});final MaintenanceRecord record;@override Widget build(BuildContext context){final icon=record.type=='oil'?CupertinoIcons.drop_fill:record.type=='pads'?CupertinoIcons.wrench:CupertinoIcons.drop;return Card(child:ListTile(contentPadding:const EdgeInsets.all(14),leading:CircleAvatar(backgroundColor:const Color(0xFFE2F9F6),child:Icon(icon,color:AppTheme.teal)),title:Text(record.title,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${record.date.day.toString().padLeft(2,'0')}/${record.date.month.toString().padLeft(2,'0')}/${record.date.year} • ${record.mileage} km${record.notes.isEmpty?'':'\n${record.notes}'}'),isThreeLine:record.notes.isNotEmpty));}}
void showPadsForm(BuildContext context){final app=ProviderScope.containerOf(context).read(appProvider);final km=TextEditingController(text:(app.vehicle?.mileage??0).toString());final notes=TextEditingController();showModalBottomSheet(context:context,isScrollControlled:true,showDragHandle:true,builder:(ctx)=>Padding(padding:EdgeInsets.fromLTRB(20,0,20,MediaQuery.of(ctx).viewInsets.bottom+24),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Pastillas de freno',style:Theme.of(ctx).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:14),_input(km,'Kilometraje del cambio',number:true),_input(notes,'Observaciones'),const SizedBox(height:18),SizedBox(width:double.infinity,child:FilledButton(onPressed:(){app.addPads(BrakePadChange(date:DateTime.now(),mileage:int.tryParse(km.text)??0,review:DateTime.now().add(const Duration(days:365)),notes:notes.text));Navigator.pop(ctx);},child:const Text('Guardar cambio')))])));}
void showFluidForm(BuildContext context){final app=ProviderScope.containerOf(context).read(appProvider);final km=TextEditingController(text:(app.vehicle?.mileage??0).toString());final notes=TextEditingController();showModalBottomSheet(context:context,isScrollControlled:true,showDragHandle:true,builder:(ctx)=>Padding(padding:EdgeInsets.fromLTRB(20,0,20,MediaQuery.of(ctx).viewInsets.bottom+24),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Líquido de frenos',style:Theme.of(ctx).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:14),_input(km,'Kilometraje actual',number:true),_input(notes,'Observaciones'),const SizedBox(height:18),SizedBox(width:double.infinity,child:FilledButton(onPressed:(){app.addFluid(BrakeFluidChange(date:DateTime.now(),mileage:int.tryParse(km.text)??0,review:DateTime.now().add(const Duration(days:730)),notes:notes.text));Navigator.pop(ctx);},child:const Text('Guardar cambio')))])));}
Widget _input(TextEditingController c,String label,{bool number=false})=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextField(controller:c,keyboardType:number?TextInputType.number:null,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder())));
